CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY AUTOINCREMENT, username TEXT NOT NULL UNIQUE COLLATE NOCASE, name TEXT NOT NULL, password_hash TEXT NOT NULL, recovery_hash TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('ADMIN','VIEWER')), active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS funds(id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('CASH','BANK','OTHER')), opening INTEGER NOT NULL DEFAULT 0, opening_date TEXT NOT NULL, note TEXT NOT NULL DEFAULT '', deleted INTEGER NOT NULL DEFAULT 0, version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS categories(id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('IN','OUT','BOTH')), note TEXT NOT NULL DEFAULT '', deleted INTEGER NOT NULL DEFAULT 0, version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS contacts(id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('CUSTOMER','SUPPLIER','EMPLOYEE','OTHER')), phone TEXT NOT NULL DEFAULT '', note TEXT NOT NULL DEFAULT '', deleted INTEGER NOT NULL DEFAULT 0, version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS obligations(id INTEGER PRIMARY KEY AUTOINCREMENT, code TEXT NOT NULL UNIQUE, kind TEXT NOT NULL CHECK(kind IN ('RECEIVABLE','PAYABLE','ADVANCE')), contact_id INTEGER NOT NULL REFERENCES contacts(id), description TEXT NOT NULL, amount INTEGER NOT NULL CHECK(amount>0 AND amount<=1000000000000), date TEXT NOT NULL, due_date TEXT, deleted INTEGER NOT NULL DEFAULT 0, version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS vouchers(id INTEGER PRIMARY KEY AUTOINCREMENT, code TEXT NOT NULL UNIQUE, type TEXT NOT NULL CHECK(type IN ('RECEIPT','EXPENSE','TRANSFER')), date TEXT NOT NULL, description TEXT NOT NULL, amount INTEGER NOT NULL CHECK(amount>0 AND amount<=1000000000000), fee INTEGER NOT NULL DEFAULT 0 CHECK(fee>=0 AND fee<=1000000000000), fund_id INTEGER NOT NULL REFERENCES funds(id), to_fund_id INTEGER REFERENCES funds(id), category_id INTEGER REFERENCES categories(id), contact_id INTEGER REFERENCES contacts(id), obligation_id INTEGER REFERENCES obligations(id), purpose TEXT NOT NULL DEFAULT '', source_key TEXT UNIQUE, source_ref TEXT NOT NULL DEFAULT '', deleted INTEGER NOT NULL DEFAULT 0, version INTEGER NOT NULL DEFAULT 1, created_by INTEGER NOT NULL REFERENCES users(id), updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, CHECK((type='TRANSFER' AND to_fund_id IS NOT NULL AND to_fund_id<>fund_id AND obligation_id IS NULL) OR (type<>'TRANSFER' AND to_fund_id IS NULL AND fee=0)));
CREATE TABLE IF NOT EXISTS clearings(id INTEGER PRIMARY KEY AUTOINCREMENT, obligation_id INTEGER NOT NULL REFERENCES obligations(id), amount INTEGER NOT NULL CHECK(amount>0), date TEXT NOT NULL, note TEXT NOT NULL, created_by INTEGER NOT NULL REFERENCES users(id));
CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY AUTOINCREMENT, actor_id INTEGER REFERENCES users(id), action TEXT NOT NULL, entity TEXT NOT NULL, entity_id INTEGER, before_json TEXT, after_json TEXT, reason TEXT NOT NULL DEFAULT '', at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TRIGGER IF NOT EXISTS audit_no_update BEFORE UPDATE ON audit BEGIN SELECT RAISE(ABORT,'Audit immutable'); END;
CREATE TRIGGER IF NOT EXISTS audit_no_delete BEFORE DELETE ON audit BEGIN SELECT RAISE(ABORT,'Audit immutable'); END;
CREATE INDEX IF NOT EXISTS voucher_date ON vouchers(date,deleted);
CREATE INDEX IF NOT EXISTS voucher_obligation ON vouchers(obligation_id,deleted);
PRAGMA user_version=1;
